#[wasm_bindgen_test]
fn thinking_fixtures_parse_to_expected() {
    for f in fixtures::THINKING {
        let actual: Value = serde_json::from_str(&prism_wasm::strip_thinking(f.input)).unwrap();
        assert_eq!(actual, expected_value(f), "{}", f.name);
    }
}

#[wasm_bindgen_test]
fn settings_fixtures_normalize_to_expected() {
    for f in fixtures::SETTINGS {
        // Compare as Settings (f32-exact), not JSON values.
        let normalized = prism_wasm::normalize_settings_json(f.input);
        let normalized: Value = serde_json::from_str(&normalized).unwrap();
        let actual: Settings =
            serde_json::from_value(normalized.get("Ok").cloned().unwrap()).unwrap();
        let expected: Settings = serde_json::from_str(f.expected).unwrap();
        assert_eq!(actual, expected, "{}", f.name);
    }
}

#[wasm_bindgen_test]
fn providers_and_defaults_are_sane() {
    let providers: Value = serde_json::from_str(&prism_wasm::providers_json()).unwrap();
    let list = providers.as_array().expect("provider array");
    assert_eq!(list.len(), 17, "provider count");
    let defaults: Value = serde_json::from_str(&prism_wasm::default_settings_json()).unwrap();
    assert_eq!(defaults["provider"], "openai");
    assert_eq!(defaults["max_tokens"], 2048);
}
